import unittest

import textstat


class TestTextStat(unittest.TestCase):
    def test_words_basic(self):
        self.assertEqual(textstat.words("the quick, brown fox!"),
                         ["the", "quick", "brown", "fox"])

    def test_word_count(self):
        self.assertEqual(textstat.word_count("one two three"), 3)

    def test_char_frequencies(self):
        self.assertEqual(textstat.char_frequencies("AbBa!"),
                         {"a": 2, "b": 2})

    def test_longest_word(self):
        self.assertEqual(textstat.longest_word("a bb ccc dd"), "ccc")

    def test_longest_word_empty(self):
        self.assertEqual(textstat.longest_word("...!"), "")

    def test_average_word_length(self):
        # "ab cd ef" -> 3 words of length 2 -> mean 2.0
        self.assertAlmostEqual(textstat.average_word_length("ab cd ef"), 2.0)

    def test_average_word_length_empty(self):
        self.assertEqual(textstat.average_word_length(""), 0.0)

    def test_palindrome_mixed_case(self):
        self.assertTrue(textstat.is_palindrome("A man, a plan, a canal: Panama"))

    def test_palindrome_negative(self):
        self.assertFalse(textstat.is_palindrome("clearly not"))

    def test_ngrams_includes_last(self):
        self.assertEqual(textstat.ngrams(["a", "b", "c"], 2),
                         [("a", "b"), ("b", "c")])


if __name__ == "__main__":
    unittest.main()
